-- ====================================================================================
-- BỘ DỮ LIỆU MẪU TOÀN DIỆN DOANH NGHIỆP THỰC TẾ (REALISTIC ENTERPRISE SEED DATA)
-- Dự án: TTCS_K1S2_N4_HeThongQuanLyKhachHang (Frostline CRM)
-- Quy mô: 50 bản ghi/bảng nghiệp vụ chuẩn hóa, liên kết quan hệ 100% không mồ côi
-- ====================================================================================

USE `crm_db`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ------------------------------------------------------------------------------------
-- 1. ĐỘI NGŨ NHÂN SỰ & TÀI KHOẢN (USERS & USER_ROLES)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `password_hash` = VALUES(`password_hash`), `full_name` = VALUES(`full_name`), `team_id` = VALUES(`team_id`), `is_active` = VALUES(`is_active`);

ON DUPLICATE KEY UPDATE `role_id` = VALUES(`role_id`);

-- ------------------------------------------------------------------------------------
-- 2. ĐỐI THỦ CẠNH TRANH (COMPETITORS)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `competitor_name` = VALUES(`competitor_name`), `status` = VALUES(`status`);

-- ------------------------------------------------------------------------------------
-- 3. CHIẾN DỊCH TIẾP THỊ (CAMPAIGNS)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `campaign_name` = VALUES(`campaign_name`), `budget` = VALUES(`budget`), `status` = VALUES(`status`);

-- ------------------------------------------------------------------------------------
-- 4. BIỂU MẪU THU THẬP LEAD TRÊN WEBSITE (LEAD_WEB_FORMS - 20 MẪU THỰC TẾ)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `form_name` = VALUES(`form_name`), `is_active` = VALUES(`is_active`);

-- ------------------------------------------------------------------------------------
-- 5. DANH MỤC KHÁCH HÀNG DOANH NGHIỆP (CUSTOMERS - 50 DOANH NGHIỆP)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `customer_name` = VALUES(`customer_name`), `phone` = VALUES(`phone`), `status` = VALUES(`status`), `owner_id` = VALUES(`owner_id`), `created_at` = VALUES(`created_at`);

-- ------------------------------------------------------------------------------------
-- 6. DANH SÁCH NGƯỜI LIÊN HỆ & BUYING CENTER (CONTACTS - 50 LIÊN HỆ)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `full_name` = VALUES(`full_name`), `position` = VALUES(`position`), `email` = VALUES(`email`);

-- ------------------------------------------------------------------------------------
-- 7. QUAN HỆ TẬP ĐOÀN & CÔNG TY MẸ - CON (CUSTOMER_RELATIONSHIPS)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `relationship_type` = VALUES(`relationship_type`);

-- ------------------------------------------------------------------------------------
-- 8. DANH MỤC SẢN PHẨM & DỊCH VỤ (PRODUCTS - 50 MÃ SẢN PHẨM)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `product_name` = VALUES(`product_name`), `list_price` = VALUES(`list_price`), `status` = VALUES(`status`);

-- ------------------------------------------------------------------------------------
-- 9. KHÁCH HÀNG TIỀM NĂNG (LEADS - 50 LEADS PHÂN BỔ TOÀN DIỆN)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `full_name` = VALUES(`full_name`), `company_name` = VALUES(`company_name`), `campaign_id` = VALUES(`campaign_id`), `owner_id` = VALUES(`owner_id`), `score` = VALUES(`score`), `status` = VALUES(`status`), `phone` = VALUES(`phone`), `email` = VALUES(`email`);

-- ------------------------------------------------------------------------------------
-- 10. CƠ HỘI BÁN HÀNG PIPELINE (OPPORTUNITIES - 50 DEAL)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `amount` = VALUES(`amount`), `campaign_id` = VALUES(`campaign_id`), `pipeline_stage_id` = VALUES(`pipeline_stage_id`), `stage` = VALUES(`stage`), `status` = VALUES(`status`);

-- ------------------------------------------------------------------------------------
-- 11. DANH SÁCH BÁO GIÁ (QUOTES - 50 BÁO GIÁ)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `quote_number` = VALUES(`quote_number`), `owner_id` = VALUES(`owner_id`);

-- ------------------------------------------------------------------------------------
-- 12. NHẬT KÝ HOẠT ĐỘNG & BIÊN BẢN TƯƠNG TÁC (ACTIVITIES - 50 LOGS)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `created_at` = VALUES(`created_at`);

-- ------------------------------------------------------------------------------------
-- 13. CHĂM SÓC KHÁCH HÀNG ĐỊNH KỲ (CUSTOMER_CARE - 50 KHÁCH HÀNG & CẤU HÌNH)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `last_contacted_at` = VALUES(`last_contacted_at`), `inactive_threshold_days` = VALUES(`inactive_threshold_days`), `note` = VALUES(`note`);

-- ------------------------------------------------------------------------------------
-- 14. YÊU CẦU HỖ TRỢ KỸ THUẬT SAU BÁN (SUPPORT_REQUESTS - 50 TICKET)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `status` = VALUES(`status`), `priority` = VALUES(`priority`);

-- ------------------------------------------------------------------------------------
-- 15. GIÁ TRỊ TRƯỜNG TÙY CHỈNH (CUSTOM_FIELD_VALUES - 100 BẢN GHI)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `field_value` = VALUES(`field_value`);

-- ------------------------------------------------------------------------------------
-- 16. LỊCH SỬ CHUYỂN CÔNG TÁC LIÊN HỆ (CONTACT_COMPANY_HISTORY - 20 BẢN GHI)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `reason` = VALUES(`reason`);

-- ------------------------------------------------------------------------------------
-- 17. QUY TẮC PHÂN BỔ LEAD (LEAD_ASSIGNMENT_RULES - 5 QUY TẮC)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `rule_name` = VALUES(`rule_name`), `criterion_value` = VALUES(`criterion_value`);

-- ------------------------------------------------------------------------------------
-- 18. BỘ LỌC TÌM KIẾM ĐÃ LƯU (SAVED_FILTERS - 10 BỘ LỌC)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `filter_name` = VALUES(`filter_name`);

-- ------------------------------------------------------------------------------------
-- 19. NHẬT KÝ THAO TÁC HỆ THỐNG (AUDIT_LOGS - 50 BẢN GHI)
-- ------------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `description` = VALUES(`description`);

SET FOREIGN_KEY_CHECKS = 1;

SELECT 'NẠP DỮ LIỆU MẪU TOÀN BỘ CÁC BẢNG HỆ THỐNG THÀNH CÔNG!' AS `Message`;
